"""Solution to the Zebra Puzzle.

Solves the puzzle by constraint satisfaction over the five houses,
assigning one value from each category (color, nation, pet, drink,
hobby) to each house so that all 15 statements hold.
"""

NATIONS = ["Englishman", "Spaniard", "Ukrainian", "Japanese", "Norwegian"]
COLORS = ["Red", "Green", "Ivory", "Yellow", "Blue"]
PETS = ["Dog", "Snail", "Fox", "Horse", "Zebra"]
DRINKS = ["Coffee", "Tea", "Milk", "Orange juice", "Water"]
HOBBIES = ["Dancing", "Reading", "Painter", "Football", "Chess"]


def _solve():
    """Return the list of houses (each a dict of category -> value)."""
    houses = [{} for _ in range(range(5))]

    def fits(house, category, value):
        # A value may be placed only if it does not contradict the house.
        if category in house and house[category] != value:
            return False
        for cat, val in house.items():
            if _conflicts(cat, val, category, value):
                return False
        return True

    def _conflicts(cat1, val1, cat2, val2):
        """True if assigning (cat2, val2) contradicts an existing (cat1, val1)."""
        if cat1 == cat2:
            return val1 != val2
        # Cross-category constraints from the statements.
        pairs = {
            ("Nation", "Englishman"): ("Color", "Red"),
            ("Nation", "Spaniard"): ("Pet", "Dog"),
            ("Color", "Green"): ("Drink", "Coffee"),
            ("Nation", "Ukrainian"): ("Drink", "Tea"),
            ("Pet", "Snail"): ("Hobby", "Dancing"),
            ("Color", "Yellow"): ("Hobby", "Painter"),
            ("Nation", "Japanese"): ("Hobby", "Chess"),
            ("Hobby", "Football"): ("Drink", "Orange juice"),
        }
        if (cat1, val1) in pairs:
            c, v = pairs[(cat1, val1)]
            if (cat2, val2) == (c, v):
                return False  # consistent
            if cat2 == c or cat2 == cat1 or val2 == val1:
                # If the two facts share a category or value, they must agree.
                return True
        if (cat2, val2) in pairs:
            c, v = pairs[(cat2, val2)]
            if (cat1, val1) == (c, v):
                return False
            if cat1 == c or cat1 == cat2 or val1 == val1 and val1 == v:
                return True
        # All categories hold distinct values; a value used in another
        # category never conflicts (values are category-specific).
        return False

    categories = ["Nation", "Color", "Pet", "Drink", "Hobby"]
    domains = {
        "Nation": NATIONS,
        "Color": COLORS,
        "Pet": PETS,
        "Drink": DRINKS,
        "Hobby": HOBBIES,
    }

    def assign(h, cat, val):
        houses[h][cat] = val

    def unassign(h, cat):
        del houses[h][cat]

    def position(value_of_category, value):
        for h in range(5):
            if houses[h].get(value_of_category) == value:
                return h
        return None

    def check_global():
        # Immediate-right: green immediately right of ivory.
        g = position("Color", "Green")
        i = position("Color", "Ivory")
        if g is not None and i is not None and g != i + 1:
            return False
        # Middle house drinks milk.
        if houses[2].get("Drink") not in (None, "Milk"):
            return False
        # Norwegian in the first house.
        if houses[0].get("Nation") not in (None, "Norwegian"):
            return False
        # Norwegian next to the blue house.
        if houses[0].get("Nation") == "Norwegian":
            if houses[1].get("Color") not in (None, "Blue"):
                return False
        # Reading next to fox.
        r = position("Hobby", "Reading")
        f = position("Pet", "Fox")
        if r is not None and f is not None and abs(r - f) != 1:
            return False
        # Painter next to horse.
        p = position("Hobby", "Painter")
        ho = position("Pet", "Horse")
        if p is not None and ho is not None and abs(p - ho) != 1:
            return False
        return True

    def search(h, cat_idx):
        if h == 5:
            return check_global()
        if cat_idx == len(categories):
            return search(h + 1, 0)
        cat = categories[cat_idx]
        for val in domains[cat]:
            if fits(h, cat, val):
                assign(h, cat, val)
                if check_global() and search(h, cat_idx + 1):
                    return True
                unassign(h, cat)
        return False

    search(0, 0)
    return houses


def _answer():
    return _solve()


def drinks_water():
    """Return the name of the resident who drinks water."""
    for house in _answer():
        if house["Drink"] == "Water":
            return house["Nation"]
    raise ValueError("No unique solution found")


def owns_zebra():
    """Return the name of the resident who owns the zebra."""
    for house in _answer():
        if house["Pet"] == "Zebra":
            return house["Nation"]
    raise ValueError("No unique solution found")

