DRINKS = ["Coffee", "Tea", "Milk", "Orange juice", "Water"]
HOBBIES = ["Dancing", "Reading", "Painter", "Football", "Chess"]

# Facts that tie two attributes to the same house. Because every value is
# unique across the five houses, each fact works in both directions.
FACTS = [
    {("Nation", "Englishman"), ("Color", "Red")},      # 2
    {("Nation", "Spaniard"), ("Pet", "Dog")},          # 3
    {("Color", "Green"), ("Drink", "Coffee")},         # 4
    {("Nation", "Ukrainian"), ("Drink", "Tea")},      # 5
    {("Pet", "Snail"), ("Hobby", "Dancing")},          # 7
    {("Color", "Yellow"), ("Hobby", "Painter")},       # 8
    {("Nation", "Japanese"), ("Hobby", "Chess")},      # 14
    {("Hobby", "Football"), ("Drink", "Orange juice")},  # 13
