        if p is not None and ho is not None and abs(p - ho) != 1:
            return False
        return True

    def search(h, ci):
        if h == 5:
            return check_global()
        if ci == len(categories):
            return search(h + 1, 0)
        cat = categories[ci]
        for val in domains[ci]:
            if any(_conflicts(c, v, cat, val) for c, v in houses[h].items()):
                continue
